    /// Builds an AST expression for the operator.
    fn into_expression(self, lhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            PostfixOperator::Factorial => ast::Expression::Operator(Factorial(Box::new(lhs))),
            PostfixOperator::Is(lit) => ast::Expression::Operator(Is(Box::new(lhs), lit)),
            PostfixOperator::IsNot(lit) => {
                ast::Expression::Operator(Not(Box::new(Is(Box::new(lhs), lit))))
            }
        }
    }
}
